// utils/visitors/{visitor}/interfaces.ts

// Éléments visités — chaque type implémente accept()
export interface {Visitor}ElementA {
  type: 'elementA'
  // Ajoute ici les champs de l'élément A
}

export interface {Visitor}ElementB {
  type: 'elementB'
  // Ajoute ici les champs de l'élément B
}

// Interface du visiteur — une méthode par type d'élément
export interface {Visitor}Visitor {
  visitElementA(element: {Visitor}ElementA): string
  visitElementB(element: {Visitor}ElementB): string
  // Ajoute ici les méthodes pour chaque type d'élément
}

// Interface Visitable — tous les éléments l'implémentent
export interface Visitable {
  accept(visitor: {Visitor}Visitor): string
}

// utils/visitors/{visitor}/{Visitor}Nodes.ts
import type { {Visitor}ElementA, {Visitor}ElementB, {Visitor}Visitor, Visitable } from './interfaces'

// Nœud A — délègue au visiteur via accept()
export class {Visitor}NodeA implements Visitable {
  constructor(public element: {Visitor}ElementA) {}

  accept(visitor: {Visitor}Visitor): string {
    return visitor.visitElementA(this.element)
  }
}

// Nœud B — délègue au visiteur via accept()
export class {Visitor}NodeB implements Visitable {
  constructor(public element: {Visitor}ElementB) {}

  accept(visitor: {Visitor}Visitor): string {
    return visitor.visitElementB(this.element)
  }
}

// Factory — crée le bon nœud selon le type de l'élément
export const create{Visitor}Node = (
  element: {Visitor}ElementA | {Visitor}ElementB
): Visitable => {
  if (element.type === 'elementA') return new {Visitor}NodeA(element)
  return new {Visitor}NodeB(element as {Visitor}ElementB)
}

// utils/visitors/{visitor}/{Visitor}Visitors.ts
import type { {Visitor}Visitor, {Visitor}ElementA, {Visitor}ElementB } from './interfaces'

// Visiteur concret A (ex: export Markdown, calcul statistiques)
export class {Visitor}VisitorA implements {Visitor}Visitor {
  visitElementA(element: {Visitor}ElementA): string {
    // Ajoute ici le traitement de l'élément A par le visiteur A
    return `A visitA: ${JSON.stringify(element)}`
  }

  visitElementB(element: {Visitor}ElementB): string {
    // Ajoute ici le traitement de l'élément B par le visiteur A
    return `B visitA: ${JSON.stringify(element)}`
  }
}

// Visiteur concret B (ex: export JSON, calcul différent)
export class {Visitor}VisitorB implements {Visitor}Visitor {
  visitElementA(element: {Visitor}ElementA): string {
    return JSON.stringify(element, null, 2)
  }

  visitElementB(element: {Visitor}ElementB): string {
    return JSON.stringify(element, null, 2)
  }
}

// composables/use{Visitor}.ts
import { create{Visitor}Node } from '~/utils/visitors/{visitor}/{Visitor}Nodes'
import { {Visitor}VisitorA, {Visitor}VisitorB } from '~/utils/visitors/{visitor}/{Visitor}Visitors'
import type { {Visitor}ElementA, {Visitor}ElementB } from '~/utils/visitors/{visitor}/interfaces'

export const use{Visitor} = () => {
  const applyVisitorA = (element: {Visitor}ElementA | {Visitor}ElementB): string => {
    const visitor = new {Visitor}VisitorA()
    const node    = create{Visitor}Node(element)
    return node.accept(visitor)
  }

  const applyVisitorB = (element: {Visitor}ElementA | {Visitor}ElementB): string => {
    const visitor = new {Visitor}VisitorB()
    const node    = create{Visitor}Node(element)
    return node.accept(visitor)
  }

  return { applyVisitorA, applyVisitorB }
}

// tests/utils/visitors/{visitor}/{Visitor}Visitors.spec.ts
import { describe, it, expect } from 'vitest'
import { {Visitor}VisitorA, {Visitor}VisitorB } from '~/utils/visitors/{visitor}/{Visitor}Visitors'
import { {Visitor}NodeA, {Visitor}NodeB, create{Visitor}Node } from '~/utils/visitors/{visitor}/{Visitor}Nodes'

const mockElementA = { type: 'elementA' as const }
const mockElementB = { type: 'elementB' as const }

describe('{Visitor}VisitorA', () => {
  const visitor = new {Visitor}VisitorA()

  it('visitElementA() traite l\'élément A', () => {
    const result = visitor.visitElementA(mockElementA)
    expect(typeof result).toBe('string')
  })

  it('visitElementB() traite l\'élément B', () => {
    const result = visitor.visitElementB(mockElementB)
    expect(typeof result).toBe('string')
  })
})

describe('{Visitor}VisitorB', () => {
  const visitor = new {Visitor}VisitorB()

  it('visitElementA() retourne un résultat différent de VisitorA', () => {
    const visitorA = new {Visitor}VisitorA()
    const resultA  = visitorA.visitElementA(mockElementA)
    const resultB  = visitor.visitElementA(mockElementA)
    // Les deux visiteurs produisent des résultats différents sur le même élément
    expect(typeof resultB).toBe('string')
  })
})

describe('accept() via create{Visitor}Node()', () => {
  it('NodeA délègue au bon visiteur', () => {
    const node    = create{Visitor}Node(mockElementA)
    const visitor = new {Visitor}VisitorA()
    const result  = node.accept(visitor)
    expect(typeof result).toBe('string')
  })

  it('NodeB délègue au bon visiteur', () => {
    const node    = create{Visitor}Node(mockElementB)
    const visitor = new {Visitor}VisitorA()
    const result  = node.accept(visitor)
    expect(typeof result).toBe('string')
  })

  it('le même nœud accepte différents visiteurs', () => {
    const node      = create{Visitor}Node(mockElementA)
    const visitorA  = new {Visitor}VisitorA()
    const visitorB  = new {Visitor}VisitorB()
    const resultA   = node.accept(visitorA)
    const resultB   = node.accept(visitorB)
    expect(resultA).not.toBe(resultB)
  })
})
